class Solution:
    def largestNumber(self, pieces: List[int]) -> str:
        s = [str(p) for p in pieces]
        changed = True
        while changed:
            changed = False
            for i in range(len(s) - 1):
                if s[i] + s[i + 1] < s[i + 1] + s[i]:
                    s[i], s[i + 1] = s[i + 1], s[i]
                    changed = True
        out = "".join(s)
        return "0" if out[0] == "0" else out

