class Solution {
    public String largestNumber(int[] pieces) {
        String[] s = new String[pieces.length];
        for (int i = 0; i < s.length; i++) s[i] = String.valueOf(pieces[i]);
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i + 1 < s.length; i++) {
                if ((s[i] + s[i + 1]).compareTo(s[i + 1] + s[i]) < 0) {
                    String t = s[i]; s[i] = s[i + 1]; s[i + 1] = t;
                    changed = true;
                }
            }
        }
        String out = String.join("", s);
        return out.charAt(0) == '0' ? "0" : out;
    }
}

